Lemma w4s_cell_upd : forall (rc : runConstT) m m' A pre c c' post,
  rw_cells asegs m A (pre ++ [c] ++ post) -> csize c' = csize c ->
  munch [(A + Z.of_nat (cells_size pre), A + Z.of_nat (cells_size pre) + Z.of_nat (csize c))] m m' -> wmono asegs m m' ->
  rw_cells asegs m' (A + Z.of_nat (cells_size pre)) [c'] -> rw_cells asegs m' A (pre ++ [c'] ++ post).
