    /\ rw_cells asegs mm SPF sa /\ cells_size sa = 136%nat
    /\ rw_cells asegs mm (SPF + 136) [C8 (Z_to_bv 64 2147450880)]
    /\ rw_cells asegs mm (SPF + 144) sb /\ cells_size sb = 96%nat
    /\ rw_cells asegs mm (SPF + 240) bd4 /\ cells_size bd4 = 40%nat
    /\ (exists jj, rw_cells asegs mm (SPF + 280) [CB 112 jj])
    /\ rw_cells asegs mm (SP + -104) FRS
    /\ mem_inv asegs mm /\ munch DW m0 mm /\ wmono asegs m0 mm.

